description:
Write `parseConfig(schema, input)` where `schema` describes the expected fields and the **return type is computed from the schema**:

```typescript
const schema = { port: "number", host: "string", debug: "boolean" } as const;
const config = parseConfig(schema, { port: 8080, host: "localhost", debug: false });
config.port.toFixed(0);       // config: { port: number; host: string; debug: boolean }
```

- Define `type FieldType = "string" | "number" | "boolean"`.
- Define `type TypeOf<F extends FieldType>`, a conditional type giving `string`, `number` or `boolean`.
- Define `type Parsed<S extends Record<string, FieldType>> = { [K in keyof S]: TypeOf<S[K]> }`, a mapped type.
- `parseConfig<S extends Record<string, FieldType>>(schema: S, input: unknown): Parsed<S>` checks that `input` is a non-null object, that every field in the schema is present with a value of the right `typeof`, and returns an object with **only** the schema's fields. Anything wrong throws a `TypeError` whose message names the field (or says the input is not an object).

solution.solution.ts:
type FieldType = "string" | "number" | "boolean";

type TypeOf<F extends FieldType> = F extends "string" ? string : F extends "number" ? number : boolean;

type Parsed<S extends Record<string, FieldType>> = { [K in keyof S]: TypeOf<S[K]> };

function parseConfig<S extends Record<string, FieldType>>(schema: S, input: unknown): Parsed<S> {
  if (typeof input !== "object" || input === null) throw new TypeError("the input is not an object");
  const source = input as Record<string, unknown>;
  const result: Record<string, unknown> = {};
  for (const key of Object.keys(schema)) {
    if (!(key in source)) throw new TypeError(`missing field: ${key}`);
    const value = source[key];
    if (typeof value !== schema[key]) throw new TypeError(`field ${key} should be a ${schema[key]}, got ${typeof value}`);
    result[key] = value;
  }
  return result as Parsed<S>;
}

unitTests:
const schema = { port: "number", host: "string", debug: "boolean" } as const;

test("valid input", () => {
  const config = parseConfig(schema, { port: 8080, host: "localhost", debug: false, extra: 1 });
  checkEq(config, { port: 8080, host: "localhost", debug: false });
  const port: number = config.port;
  checkEq(port + 1, 8081);
});

test("wrong input", () => {
  for (const [bad, field] of [
    [{ port: "8080", host: "h", debug: true }, "port"],
    [{ port: 1, debug: true }, "host"],
    [{ port: 1, host: "h", debug: "yes" }, "debug"],
  ] as const) {
    let message = "";
    try { parseConfig(schema, bad); } catch (e) { message = (e as Error).message; check(e instanceof TypeError, "should be a TypeError"); }
    check(message.includes(field), `the message should name ${field}: ${message}`);
  }
  checkThrows(() => parseConfig(schema, null), TypeError);
  checkThrows(() => parseConfig(schema, "port=1"), TypeError);
});

